<?php
namespace App\Actions\Catalog;
use App\Models\CatalogEntity; use App\Models\ModerationAction; use App\Models\ModerationReport; use App\Services\AuditLogger; use App\Services\PlatformNotifier; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class SubmitCatalogDomain
{
    public function __construct(private AuditLogger $audit,private PlatformNotifier $notifier) {}
    public function execute(CatalogEntity $entity,string $domain,$actor,array $requirements=[]): CatalogEntity { return DB::transaction(function()use($entity,$domain,$actor,$requirements){$entity=CatalogEntity::lockForUpdate()->findOrFail($entity->id);abort_unless($entity->serviceType()->where('code',$domain)->exists(),404);if(!in_array($entity->status,['draft','rejected'],true))throw ValidationException::withMessages(['status'=>'Lifecycle tidak mengizinkan pengajuan.']);$missing=[];foreach(['category_id'=>'kategori','region_id'=>'wilayah','description'=>'deskripsi','address'=>'alamat'] as $field=>$label)if(blank($entity->$field))$missing[]=$label;if(!$entity->location)$missing[]='koordinat';if(!$entity->media()->wherePivot('role','cover')->exists())$missing[]='media cover';foreach($requirements as $ok=>$label)if(!$ok)$missing[]=$label;if($missing)throw ValidationException::withMessages(['status'=>'Lengkapi: '.implode(', ',$missing).'.']);$from=$entity->status;$entity->update(['status'=>'submitted','published_at'=>null]);$report=ModerationReport::create(['reporter_user_id'=>$actor->id,'mitra_id'=>$entity->mitra_id,'catalog_entity_id'=>$entity->id,'reason_code'=>$domain.'_publication_review','status'=>'open']);ModerationAction::create(['report_id'=>$report->id,'actor_user_id'=>$actor->id,'action_type'=>'submitted','from_status'=>$from,'to_status'=>'submitted']);$this->audit->record($domain.'.submitted',$entity,['status'=>$from],['status'=>'submitted'],$actor);$this->notifier->administrators($domain.'.submitted',$entity->mitra_id,['catalog_entity_id'=>$entity->id]);return $entity->fresh();}); }
}
